// slides/slide-01.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'DeepSeek-V2: A Strong, Economical, and Efficient MoE Language Model'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative background elements
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.2,
    fill: { color: theme.primary }
  });

  slide.addShape(pres.shapes.OVAL, {
    x: -1, y: -2, w: 4, h: 4,
    fill: { color: theme.light, transparency: 80 }
  });

  slide.addShape(pres.shapes.OVAL, {
    x: 8, y: 4, w: 3, h: 3,
    fill: { color: theme.secondary, transparency: 80 }
  });

  // Main Title
  slide.addText("DeepSeek-V2", {
    x: 0.5, y: 1.2, w: 9, h: 1.0,
    fontSize: 72, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Subtitle
  slide.addText("A Strong, Economical, and Efficient MoE Language Model", {
    x: 0.5, y: 2.3, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.secondary, bold: false, align: "left"
  });

  // Key Stats Badges
  const badgeY = 3.6;
  const badgeH = 0.4;

  // Badge 1: Parameters
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: badgeY, w: 3.5, h: badgeH,
    fill: { color: theme.accent }, rectRadius: 0.2
  });
  slide.addText("236B Total / 21B Activated Params", {
    x: 0.5, y: badgeY, w: 3.5, h: badgeH,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Badge 2: Context
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 4.2, y: badgeY, w: 2.0, h: badgeH,
    fill: { color: theme.accent }, rectRadius: 0.2
  });
  slide.addText("128K Context", {
    x: 4.2, y: badgeY, w: 2.0, h: badgeH,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.5, w: 9, h: 0.02,
    fill: { color: theme.secondary, transparency: 50 }
  });

  // Attribution
  slide.addText("Based on: arXiv:2405.04434", {
    x: 0.5, y: 4.7, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, bold: false, align: "left", italic: true
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

// slides/slide-02.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'The LLM Scaling Dilemma: Performance vs. Training Cost and Inference Speed'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Page title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Title underline
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 2, h: 0.04,
    fill: { color: theme.secondary }
  });

  // Two columns for the dilemma
  const colY = 1.6;
  const colW = 4.2;
  const colH = 3.2;

  // Left Column: The Goal
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: colY, w: colW, h: colH,
    fill: { color: theme.light, transparency: 40 }, rectRadius: 0.1
  });

  slide.addText("The Goal: Higher Intelligence", {
    x: 0.7, y: colY + 0.2, w: colW - 0.4, h: 0.4,
    fontSize: 22, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center"
  });

  slide.addText("Scaling up model size (parameters) consistently yields better reasoning, knowledge, and capabilities.", {
    x: 0.7, y: colY + 0.8, w: colW - 0.4, h: 0.8,
    fontSize: 16, fontFace: "Arial",
    color: theme.primary, align: "left"
  });

  // Arrow in middle
  slide.addShape(pres.shapes.RIGHT_ARROW, {
    x: 4.8, y: colY + 1.4, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });

  // Right Column: The Bottlenecks
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 5.3, y: colY, w: colW, h: colH,
    fill: { color: theme.light, transparency: 40 }, rectRadius: 0.1
  });

  slide.addText("The Bottlenecks", {
    x: 5.5, y: colY + 0.2, w: colW - 0.4, h: 0.4,
    fontSize: 22, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center"
  });

  slide.addText([
    { text: "1. Training Costs\n", options: { bold: true, fontSize: 18, color: theme.secondary } },
    { text: "Dense models require activating all parameters for every token, leading to prohibitive compute costs.\n\n", options: { fontSize: 14 } },
    { text: "2. Inference Speed (KV Cache)\n", options: { bold: true, fontSize: 18, color: theme.secondary } },
    { text: "Autoregressive generation is bottlenecked by the size of the Key-Value (KV) cache stored in memory.", options: { fontSize: 14 } }
  ], {
    x: 5.5, y: colY + 0.8, w: colW - 0.4, h: 2.0,
    fontFace: "Arial", color: theme.primary, align: "left"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

// slides/slide-03.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: 'DeepSeek-V2 Architecture: MLA + DeepSeekMoE'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Page title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.5,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Title underline
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.0, w: 2, h: 0.04,
    fill: { color: theme.secondary }
  });

  // Image section (left)
  slide.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.5, y: 1.2, w: 4.5, h: 3.8,
    sizing: { type: "contain" }
  });

  // Caption for image
  slide.addText("Fig 1: DeepSeek-V2 Transformer Block Architecture", {
    x: 0.5, y: 5.1, w: 4.5, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.primary, italic: true, align: "center"
  });

  // Content section (right)
  const rightX = 5.2;

  slide.addText("Innovating the Transformer Block", {
    x: rightX, y: 1.2, w: 4.3, h: 0.4,
    fontSize: 22, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  // Point 1: MLA
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: rightX, y: 1.8, w: 4.3, h: 1.4,
    fill: { color: theme.light, transparency: 50 }, rectRadius: 0.1
  });

  slide.addText("1. Multi-Head Latent Attention (MLA)", {
    x: rightX + 0.2, y: 1.9, w: 3.9, h: 0.3,
    fontSize: 18, fontFace: "Arial", color: theme.secondary, bold: true
  });

  slide.addText("Replaces standard Multi-Head Attention.\nCompresses the KV cache to solve inference bottlenecks while maintaining performance.", {
    x: rightX + 0.2, y: 2.3, w: 3.9, h: 0.8,
    fontSize: 14, fontFace: "Arial", color: theme.primary, bullet: true
  });

  // Point 2: DeepSeekMoE
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: rightX, y: 3.4, w: 4.3, h: 1.4,
    fill: { color: theme.light, transparency: 50 }, rectRadius: 0.1
  });

  slide.addText("2. DeepSeekMoE", {
    x: rightX + 0.2, y: 3.5, w: 3.9, h: 0.3,
    fontSize: 18, fontFace: "Arial", color: theme.secondary, bold: true
  });

  slide.addText("Replaces dense Feed-Forward Networks (FFN).\nUses highly sparse routing (activating only 21B out of 236B parameters per token) to drastically reduce training costs.", {
    x: rightX + 0.2, y: 3.9, w: 3.9, h: 0.8,
    fontSize: 14, fontFace: "Arial", color: theme.primary, bullet: true
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

// slides/slide-04.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Multi-Head Latent Attention Compresses KV Cache by 93.3%'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Page title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.5,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Title underline
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.0, w: 2, h: 0.04,
    fill: { color: theme.secondary }
  });

  // Text Content (Left)
  const leftW = 3.8;

  slide.addText([
    { text: "The Problem with MHA\n", options: { bold: true, fontSize: 18, color: theme.secondary } },
    { text: "Conventional Multi-Head Attention (MHA) stores full key-value pairs per head. Alternatives like GQA/MQA reduce cache but sacrifice performance.\n\n", options: { fontSize: 14 } },
    { text: "The MLA Solution\n", options: { bold: true, fontSize: 18, color: theme.secondary } },
    { text: "MLA introduces low-rank key-value joint compression. Instead of caching full vectors, it caches a compact latent vector.\n\n", options: { fontSize: 14 } },
    { text: "Key Mechanisms:\n", options: { bold: true, fontSize: 16 } }
  ], {
    x: 0.5, y: 1.3, w: leftW, h: 2.5,
    fontFace: "Arial", color: theme.primary, align: "left"
  });

  slide.addText([
    { text: "Decoupled RoPE for positional encoding\n" },
    { text: "On-the-fly reconstruction via learned projection matrices\n" },
    { text: "Performance exceeds MHA with drastically less cache" }
  ], {
    x: 0.5, y: 3.5, w: leftW, h: 1.0,
    fontSize: 14, fontFace: "Arial", color: theme.primary, align: "left", bullet: true
  });

  // Image Content (Right)
  slide.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 4.6, y: 1.2, w: 4.9, h: 3.8,
    sizing: { type: "contain" }
  });

  slide.addText("Fig 2: Attention mechanism comparison (MHA vs GQA vs MQA vs MLA)", {
    x: 4.6, y: 5.1, w: 4.9, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.primary, italic: true, align: "center"
  });

  // Page number badge
