module.exports = { createSlide, slideConfig };

// slides/slide-05.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'DeepSeekMoE: Fine-Grained Experts with Shared Expert Isolation'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Page title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.5,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Title underline
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.0, w: 2, h: 0.04,
    fill: { color: theme.secondary }
  });

  // Grid layout for MoE features
  const startY = 1.4;
  const gapY = 1.0;
  const colW = 4.2;

  // Box 1
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: startY, w: colW, h: 0.8,
    fill: { color: theme.light, transparency: 70 }, rectRadius: 0.1
  });
  slide.addText([
    { text: "Two Expert Types\n", options: { bold: true, fontSize: 16, color: theme.secondary } },
    { text: "Shared experts (always active for common knowledge) and Routed experts (sparsely activated via top-K).", options: { fontSize: 13 } }
  ], { x: 0.6, y: startY + 0.1, w: colW - 0.2, h: 0.6, fontFace: "Arial", color: theme.primary });

  // Box 2
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: startY + gapY, w: colW, h: 0.8,
    fill: { color: theme.light, transparency: 70 }, rectRadius: 0.1
  });
  slide.addText([
    { text: "Fine-Grained Segmentation\n", options: { bold: true, fontSize: 16, color: theme.secondary } },
    { text: "Increases specialization potential by having many smaller experts rather than a few large ones.", options: { fontSize: 13 } }
  ], { x: 0.6, y: startY + gapY + 0.1, w: colW - 0.2, h: 0.6, fontFace: "Arial", color: theme.primary });

  // Box 3
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: startY + (gapY * 2), w: colW, h: 0.8,
    fill: { color: theme.light, transparency: 70 }, rectRadius: 0.1
  });
  slide.addText([
    { text: "Device-Limited Routing\n", options: { bold: true, fontSize: 16, color: theme.secondary } },
    { text: "Constrains tokens to experts on at most M devices, significantly reducing cross-node communication overhead.", options: { fontSize: 13 } }
  ], { x: 0.6, y: startY + (gapY * 2) + 0.1, w: colW - 0.2, h: 0.6, fontFace: "Arial", color: theme.primary });

  // Box 4
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: startY + (gapY * 3), w: colW, h: 0.8,
    fill: { color: theme.light, transparency: 70 }, rectRadius: 0.1
  });
  slide.addText([
    { text: "Load Balancing\n", options: { bold: true, fontSize: 16, color: theme.secondary } },
    { text: "Auxiliary losses balance load across experts and devices. Token-dropping prevents overflow during training.", options: { fontSize: 13 } }
  ], { x: 0.6, y: startY + (gapY * 3) + 0.1, w: colW - 0.2, h: 0.6, fontFace: "Arial", color: theme.primary });


  // Right side visual representation (abstract MoE)
  const rightX = 5.2;

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: rightX, y: startY, w: 4.3, h: 3.8,
    fill: { color: theme.light, transparency: 40 }, rectRadius: 0.1
  });

  slide.addText("DeepSeekMoE Routing Mechanism", {
    x: rightX, y: startY + 0.2, w: 4.3, h: 0.3,
    fontSize: 16, fontFace: "Arial", bold: true, align: "center", color: theme.primary
  });

  // Draw Shared Experts (always on)
  slide.addText("Shared Experts (Always Active)", { x: rightX + 0.5, y: startY + 0.7, w: 3.3, h: 0.3, fontSize: 12, fontFace: "Arial", color: theme.secondary });
  for(let i=0; i<3; i++) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: rightX + 0.5 + (i * 1.1), y: startY + 1.0, w: 0.9, h: 0.4,
      fill: { color: theme.secondary }, line: { color: theme.primary, width: 1 }
    });
  }

  // Draw Router
  slide.addShape(pres.shapes.OVAL, {
    x: rightX + 1.6, y: startY + 1.7, w: 1.1, h: 0.5,
    fill: { color: theme.accent }
  });
  slide.addText("Top-Kr Router", {
    x: rightX + 1.6, y: startY + 1.7, w: 1.1, h: 0.5,
    fontSize: 10, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Draw Routed Experts
  slide.addText("Routed Experts (Sparsely Activated)", { x: rightX + 0.5, y: startY + 2.4, w: 3.3, h: 0.3, fontSize: 12, fontFace: "Arial", color: theme.secondary });
  for(let row=0; row<2; row++) {
    for(let col=0; col<4; col++) {
      // Highlight some as "routed"
      const isActive = (row === 0 && col === 1) || (row === 1 && col === 3);
      slide.addShape(pres.shapes.RECTANGLE, {
        x: rightX + 0.3 + (col * 0.95), y: startY + 2.7 + (row * 0.5), w: 0.8, h: 0.35,
        fill: { color: isActive ? theme.accent : theme.bg }, line: { color: theme.primary, width: 1 }
      });
    }
  }

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
